def count_alpha_dig_spl(input_string):
    count = {
        'alphabets': 0,
        'digits': 0,
        'special_chars': 0
    }

    for char in input_string:
        if char.isalpha():
            count['alphabets'] += 1
        elif char.isdigit():
            count['digits'] += 1
        elif char in "!@#$%^&*()_+-=[]{}|;':\",./<>?":
